                meaningBn = "১. বলুন, তিনিই আল্লাহ, একক-অদ্বিতীয়। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং তাঁকেও জন্ম দেওয়া হয়নি। আর তাঁর সমকক্ষ কেউই নেই।\n\n২. বলুন, আমি আশ্রয় চাই উষার রবের নিকট। তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে। রাতের অন্ধকারের অনিষ্ট হতে যখন তা সমাগত হয়। গিরায় ফুঁৎকারকারী নারীদের অনিষ্ট হতে। এবং হিংসুকের অনিষ্ট হতে যখন সে হিংসা করে।\n\n৩. বলুন, আমি আশ্রয় চাই মানুষের প্রতিপালকের নিকট। মানুষের অধিপতির নিকট। মানুষের সত্য উপাস্যের নিকট। আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট হতে। যে মানুষের অন্তরে কুমন্ত্রণা দেয়—জিন ও মানুষের মধ্য থেকে।",
                fojilotBn = "📖 সহীহ হাদীসের আলোকে ফজিলত ও উপকারিতা:\n১. যাবতীয় অনিষ্টের জন্য যথেষ্ট: হযরত আব্দুল্লাহ ইবনে খুবাইব (রা.) বর্ণনা করেন, রাসূলুল্লাহ (ﷺ) ইরশাদ করেছেন: \"তুমি সকাল ও সন্ধ্যায় যখন উপনীত হও তখন তিন বার করে 'ক্বুল হুওয়াল্লাহু আহাদ' এবং মু'আওবিযাতাইন (সূরা ফালাক্ব ও সূরা নাস) পাঠ করবে; এটি তোমাকে যাবতীয় ক্ষতি, বিপদ-আপদ, যাদু-টোনা ও অকল্যাণ থেকে রক্ষা করতে সবকিছুর জন্য যথেষ্ট হবে।\"\n২. জিন ও বদনজর থেকে নিষ্কৃতি: নবীজী (ﷺ) সর্বদা সকাল ও সন্ধ্যায় এ তিন সূরা পড়ে হাতে ফুঁক দিয়ে সারা শরীরে বুলিয়ে নিতেন।",
