                meaningBn = "\"এবং আপনার রবের সপ্রশংস পবিত্রতা ঘোষণা করুন সূর্যোদয়ের পূর্বে (সকালে) এবং সূর্যাস্তের পূর্বে (সন্ধ্যায়)।\" [সূরা ক্বাফ: ৩৯]",
                fojilotBn = "📖 সকাল-সন্ধ্যার জিকিরের ৫টি সুবর্ণ সুন্নাত আদব ও ফিকহী নির্দেশনা:\n\n১. সকালের যিকিরের উত্তম সময়সীমা:\nফজর উদয় (সুবহে সাদিক) থেকে সূর্যোদয় পর্যন্ত সময় সকালের যিকিরের সর্বোত্তম সময়। তবে কোনো কারণে বিলম্ব হলে সূর্যোদয়ের পরও চাশতের সময় বা দুপুরের পূর্ব পর্যন্ত পাঠ করা যাবে এবং সকালের পূর্ণ সাওয়াব পাওয়া যাবে।\n\n২. সন্ধ্যার যিকিরের উত্তম সময়সীমা:\nআসরের সালাতের পর থেকে সূর্যাস্ত পর্যন্ত সময় সন্ধ্যার যিকিরের শ্রেষ্ঠ সময়। তবে মাগরিবের পর কিংবা এশার পরেও ঘুমানোর পূর্ব পর্যন্ত পড়লে সন্ধ্যার ফজিলত অর্জিত হয়।\n\n৩. ওযু ছাড়া ও অপবিত্র অবস্থায় পাঠের বিধান:\nসকাল-সন্ধ্যার জিকির ও দোয়াসমূহ ওযু ছাড়াও মুখে পাঠ করা সম্পূর্ণ জায়েয ও বিশুদ্ধ। এমনকি বিশেষ দিনগুলোতে মা-বোনেরা জিকির ও দোয়ার নিয়তে আয়াতুল কুরসী, তিন কুল সহ সকল সকাল-সন্ধ্যার দো'আ নির্দ্বিধায় পাঠ করতে পারবেন।\n\n৪. একাগ্রতা ও হৃদয়ের উপস্থিতি:\nদোয়ার শব্দগুলোর অর্থ অন্তরে অনুভব করে ধীরস্থিরভাবে পাঠ করা সুন্নাত। রাসূলুল্লাহ (ﷺ) বলেছেন: \"জেনে রেখো, আল্লাহ কোনো গাফেল ও অমনোযোগী অন্তরের দো'আ কবুল করেন না।\" (জামে আত-তিরমিযী: ৩৪৭৯)।\n\n৫. নিয়মিত আমল ও কাজা করা:\nপ্রতিদিন এই আমলগুলো জীবনে অটুট দুর্গস্বরূপ। কোনো কারণে নির্দিষ্ট সময়ে ছুটে গেলে যখনই স্মরণ হবে তখনই পড়ে নেওয়া সালাফে সালেহীনদের পরীক্ষিত সুন্নাত।",
                detailsBn = "সকাল ও সন্ধ্যার এই মাসনূন আমলগুলো মুমিনের জন্য দৈনন্দিন আত্মিক শক্তি, মানসিক প্রশান্তি এবং পার্থিব ও অপার্থিব সুরক্ষার সর্বোত্তম উপায়।",
                referenceBn = "সূরা ক্বাফ: ৩৯; সূরা ত্বা-হা: ১৩০; ফাতহুল বারী (১১/১১৮); যাদুল মা'আদ (২/৩৩৭)"
            )
